def get_Inv_Count(arr):
    def merge_count_split_inv(left, right):
        i, j = 0, 0
        inv_count = 0
        sorted_arr = [0] * len(arr)
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                sorted_arr[i+j] = left[i]
                i += 1
            else:
                sorted_arr[i+j] = right[j]
                inv_count += len(left) - i
                j += 1
        for l in range(i, len(left)):
            sorted_arr[l+i] = left[l]
        for r in range(j, len(right)):
            sorted_arr[l+i] = right[r]
        return inv_count

    def merge_sort(arr):
        if len(arr) <= 1:
            return arr
        mid = len(arr) // 2
        left = arr[:mid]
        right = arr[mid:]
        left = merge_sort(left)
        right = merge_sort(right)
        return left + right

    sorted_arr = merge_sort(arr)
    return merge_count_split_inv(sorted_arr, sorted_arr)
