def sumofFactors(n):
    if n == 1:
        return 0
    total = 1  # 1 is always a factor
    # Check for each number from 2 to sqrt(n)
    for i in range(2, int(math.sqrt(n)) + 1):
        count = 0
        current_sum = 1
        current_term = 1
        while n % i == 0:
            count += 1
            n //= i
            current_term *= i
            if count == 1:
                current_sum += current_term
            else:
                current_sum += current_term * (i - 1)
        total *= current_sum
    if n >= 2:
        total *= 1 + n
    return total
