def sum_Of_Subarray_Prod(arr):
    n = len(arr)
    if n == 1:
        return arr[0]

    prefix_sum = [0] * n
    suffix_sum = [0] * n
    prefix_sum[0] = arr[0]
    suffix_sum[n-1] = arr[n-1]

    for i in range(1, n):
        prefix_sum[i] = prefix_sum[i-1] + arr[i]

    for i in range(n-2, -1, -1):
        suffix_sum[i] = suffix_sum[i+1] + arr[i]

    result = 0
    for i in range(n):
        result += arr[i] * (prefix_sum[i] - arr[i]) * (suffix_sum[i] - arr[i])

    return result

