def max_sum_list(lists):
    def helper(lst, current_sum, index):
        if index == len(lst):
            return current_sum
        max_sum = -float('inf')
        for i in range(len(lst[index])):
            max_sum = max(max_sum, helper(lst, current_sum + lst[index][i], index + 1))
        return max_sum

    return max(list(map(helper, lists, [0] * len(lists), range(len(lists)))))

